import{_ as r,C as n,o,c as s,j as t,a as i,E as p,a6 as l}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"(观点) 最佳在线业务细分领域","description":"","frontmatter":{"title":"(观点) 最佳在线业务细分领域","originalTitle":"(Opinion) The Best Online Business Niche","date":"2022-01-21","originalUrl":"https://thedankoe.com/letters/opinion-the-best-online-business-niche/","minutes":7,"sourceHash":"176c06313f5890ffa52782c9b97b06a5b5588db93c749947b94b215307334cc5","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/opinion-the-best-online-business-niche/"}]]},"headers":[],"relativePath":"letters/opinion-the-best-online-business-niche.md","filePath":"letters/opinion-the-best-online-business-niche.md"}'),h={name:"letters/opinion-the-best-online-business-niche.md"};function m(c,e,u,d,b,_){const a=n("ArticleMeta");return o(),s("div",null,[e[0]||(e[0]=t("h1",{id:"观点-最佳在线业务细分领域",tabindex:"-1"},[i("(观点) 最佳在线业务细分领域 "),t("a",{class:"header-anchor",href:"#观点-最佳在线业务细分领域","aria-label":'Permalink to "(观点) 最佳在线业务细分领域"'},"​")],-1)),p(a),e[1]||(e[1]=l('<p><a href="https://open.spotify.com/embed/episode/6OWJtetVSA439g03uX2uMm?si=jydF-cw0Tce0Lo89Q_1feQ&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当我刚开始涉足在线业务时，我很迷茫。我经历了现在看到其他人正在经历的所有问题。</p><p>对自己的细分领域、技能组合、产品/服务、获客机制以及其他一切都优柔寡断。我陷入了一个死循环：不断联系本地企业，赚着还算过得去的钱，但我心里清楚，自己并没有在建立任何形式的杠杆。</p><p>多年后，一切终于豁然开朗——对你来说也会如此——但我真希望自己能早点明白。</p><h2 id="c2c-商业模式" tabindex="-1"><strong>C2C 商业模式</strong> <a class="header-anchor" href="#c2c-商业模式" aria-label="Permalink to &quot;**C2C 商业模式**&quot;">​</a></h2><p>我们都听说过 B2B 和 B2C 模式。对于不了解的人来说，B2B 即“企业对企业”。想象一家向本地企业销售营销服务的代理机构。B2C 即“企业对消费者”。就像一家向个人卖咖啡的电商网店。</p><p>随着社交媒体已经——并将继续——发展成为数字商业的命脉，人们对人际连接的渴望也会随之增长。大多数企业都明白建立“在线形象”的重要性。你可以在网上买到你需要的一切。杂货、必需品、家具，应有尽有。</p><p>这种趋势已经在高速发展，但我预测，未来的主导权将继续转移到<em>个人、创作者</em>手中。亚马逊（Amazon）永远会占据优势，但较小的品牌将继续在个性化领域蓬勃发展（而且如果他们愿意，他们随时可以在亚马逊上销售）。</p><p><em>“地球上有 70 亿人。我希望未来的某一天，会有 70 亿家企业。” —— 纳瓦尔（Naval）(?)</em></p><p>于是，C2C 商业模式应运而生。创作者对创作者。个人品牌对个人品牌。个人对“精品”店。我直到开始积累受众群体时才接触到这个模式。现在，我所做的一切都围绕着与那些能解决我问题的个人创作者合作展开。</p><p>这里常见的误解是，创作者只卖课程、教练辅导、自由职业服务或其他类型的数字产品和服务。这简直大错特错。有人卖自制砧板、草药补剂、健身补剂、牛肝肉干，以及毫不夸张地说，任何你能在亚马逊上找到的东西。他们可以通过自己的受众、电子邮件列表、其他数字资产以及任何其他免费/付费流量机制（亚马逊、谷歌广告、Facebook 广告、网红和博客营销等）来销售他们的产品。</p><p>简而言之，C2C 商业模式和任何其他模式一样——但它拥有无限的扩展性，不需要庞大的团队或员工，并让你完全掌控自己的时间。就像文艺复兴时期——在城市里与人们交易你的商品——但加上了互联网的强大力量。那是能够触及任何人的能力。</p><h2 id="为什么你应该加入创作者经济" tabindex="-1"><strong>为什么你应该加入创作者经济</strong> <a class="header-anchor" href="#为什么你应该加入创作者经济" aria-label="Permalink to &quot;**为什么你应该加入创作者经济**&quot;">​</a></h2><p>它正在像野火一样蔓延。人们开始意识到，个人品牌比任何其他类型的获客机制都更具影响力。这就是个人品牌的本质：一个为你产品或服务引流的获客机制。最酷的是，你所要做的仅仅是谈论你的兴趣、你正在学习的东西以及你的专业知识。人们想和你合作，因为他们在人性层面与你产生了共鸣。</p><p>至于你可以卖什么，那可以是任何东西。如果你是个新手且想赚“快”钱，那就开始做自由职业或教练业务吧。各种形式的创作者都需要网页设计、电子邮件营销、销售成单手、绩效辅导、男性气质辅导、SaaS 开发、优质的实体产品，以及任何你能卖给正规企业的东西。优势在哪？他们比其他企业容易接触 10 倍。想联系他们？<em>给他们发个私信 (DM)</em>。就这么简单。</p><p>(附注：你可以在 <a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">Modern Mastery HQ</a> 内部学习所有这些技能、如何建立个人品牌，以及究竟如何赚到你的第一个 3,000 美元、5,000 美元和首个 6 位数收入。这里有经过验证的策略和系统。如果你坚持到底却没赚到钱——我会把你付给我的每一分钱都退给你。)</p><p>最赚钱的电商品牌往往是那些个性化的品牌。他们销售符合特定个人兴趣和需求的产品或服务。他们甚至通过具有同样兴趣的个人品牌和网红进行营销。通过了解如何启动和发展个人品牌，你就自带了这种个性化的特质。你消除了该领域存在的任何饱和与竞争，<em>因为没有人能复制你的个性。</em></p><h2 id="如何通过自我提升加入创作者经济" tabindex="-1"><strong>如何通过自我提升加入创作者经济</strong> <a class="header-anchor" href="#如何通过自我提升加入创作者经济" aria-label="Permalink to &quot;**如何通过自我提升加入创作者经济**&quot;">​</a></h2><p>如果人们只是简单地追求自己的兴趣，解决自己生活和业务上的问题，将解决方案系统化，并将它们卖给那些决定在<em>他们自己</em>的生活中解决不同问题的人，你就能赚到钱，而且完全没有竞争。</p><p>成为一名创作者是一种高度精神层面的体验。自我反思和自我认知会教会你了解人性、说服力、情感触发点，以及其他一切能帮助你捕获并转化注意力的东西。在这个领域，你必须学会让直觉引领你。你必须剥离那些错误的认知和身份认同，让你真实的自我闪耀光芒。一旦做到了这一点，生活和商业就会成为你的一种自然优势。</p><p>服务型业务和在线教育路线具有最低的风险和最低的进入壁垒。</p><p><em>以下是作为创作者、教练、自由职业者或数字产品创作者，我会采取的将任何技能或兴趣变现的步骤。</em></p><blockquote><p>研究你的兴趣<br> 创办一项服务型业务<br> 积累受众群体<br> 免费为他人工作<br> 形成你的流程<br> 提高价格<br> 重复步骤 5-6<br> 将你的流程产品化\\</p><p>这需要 2 年时间，潜力是实现每月 5 万美元以上的收入及每天工作 3 小时\\</p><p>读大学需要 4 年时间，潜力是实现每月 1 万美元的收入及每天工作 9 小时</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1480875904104599553?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">January 11, 2022</a></p></blockquote><h3 id="_1-研究一项已经有人在变现-并且与你契合-的技能或兴趣。" tabindex="-1"><strong>1) 研究一项已经有人在变现（并且与你契合）的技能或兴趣。</strong> <a class="header-anchor" href="#_1-研究一项已经有人在变现-并且与你契合-的技能或兴趣。" aria-label="Permalink to &quot;**1) 研究一项已经有人在变现（并且与你契合）的技能或兴趣。**&quot;">​</a></h3><p>事实是，如今你可以把任何东西变现。更好的是，如果已经有人从中赚钱，你也可以赚到钱。记住：一个坚实的个人品牌能消除竞争。<em>在一个“饱和”的领域中已经有资金在流动。不要试图在没有资金流动的地方赚钱。</em></p><p>如果你关注了很多健身达人，很懂健身，并且自己也取得了一些成果——这就是一条好路线。你在社交媒体上关注的任何人也都同理。很有可能你正在向他们学习，并且很了解这个话题，完全可以帮助其他人取得不错的成果。</p><h3 id="_2-开始创作内容并了解你选择的社交平台。" tabindex="-1"><strong>2) 开始创作内容并了解你选择的社交平台。</strong> <a class="header-anchor" href="#_2-开始创作内容并了解你选择的社交平台。" aria-label="Permalink to &quot;**2) 开始创作内容并了解你选择的社交平台。**&quot;">​</a></h3><p>我偏爱 Twitter（很明显）。第一，因为它是一个写作平台。你不需要去学如何设计或录制图形及视频。第二，转发按钮能把你展现给一整个受众群体，你可以比在其他平台上成长得快得多（比如 JK Molina 教授的那些旨在 <a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">在 MMHQ 内部以创纪录的时间获得你最初的 2000 个高质量粉丝</a> 的策略）</p><p>学习如何通过写作来成长和提炼你的思想，这本身就是极具价值的回报。当到了变现的时候，情况会更好。</p><h3 id="_3-与他人建立联系并提供帮助。" tabindex="-1"><strong>3) 与他人建立联系并提供帮助。</strong> <a class="header-anchor" href="#_3-与他人建立联系并提供帮助。" aria-label="Permalink to &quot;**3) 与他人建立联系并提供帮助。**&quot;">​</a></h3><p>所有的在线企业主都会同意我说的这句话：钱是在私信（DMs）里赚到的（特别是在刚起步时）。这是增加受众群体和促成交易的关键。</p><p>当你刚刚起步时，你必须与他人交流并免费帮助他们解决问题。在你的专业领域给他们提供建议，和他们通电话，了解他们的生活或业务，并给予帮助。</p><p>我将在周二的播客节目“上大学还是做生意？”中更多地谈论这个话题，届时我会深入讲解所有这些步骤。</p><h3 id="_4-开始收费。" tabindex="-1"><strong>4) 开始收费。</strong> <a class="header-anchor" href="#_4-开始收费。" aria-label="Permalink to &quot;**4) 开始收费。**&quot;">​</a></h3><p>在你帮助了别人并累积了下一个量级的实战经验后——开始收费，最低 1000 美元起步。<a href="https://youtu.be/kC1IvnzM_-A?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">你可以看看我前不久发布的这个 YouTube 视频来了解具体的流程。</a></p><h3 id="_5-提高价格并产品化。" tabindex="-1"><strong>5) 提高价格并产品化。</strong> <a class="header-anchor" href="#_5-提高价格并产品化。" aria-label="Permalink to &quot;**5) 提高价格并产品化。**&quot;">​</a></h3><p>现在你已经大幅提高了价格，并且每个月都能拿下 3 到 4 个支付 5,000 美元的客户，你就可以进行产品化了。也就是说，你可以把你那个能带来成果的系统转化为数字产品，然后<em>通过你这一直以来建立的受众群体</em>进行销售。</p><p>在你达到这个阶段之前，不要担心这一步。通过高客单价实现每月 1 万美元的收入并拥有 10,000 名粉丝。如果做法正确，可能需要 6-12 个月才能达到这个目标。也许会更长。如果你执行得完美，也许会更短，但你毕竟是凡人。</p><p>这就是这封信的全部内容。</p><p>我有太多的话题想写，但我很兴奋能在每个周五把它们发送给你。</p><p>感谢你的阅读——也感谢你对本通讯的支持。祝你度过一个不可思议的周末，我的朋友。</p><p>Dan Koe</p><hr><p><a href="/en/letters/opinion-the-best-online-business-niche">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',44))])}const k=r(h,[["render",m]]);export{g as __pageData,k as default};
